{"command":"cat <<'EOF' > probe.py
import subprocess
import re
import json

def run_cppcheck(args):
    try:
        res = subprocess.run(['./executable'] + args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        return res.returncode, res.stdout.strip(), res.stderr.strip()
    except Exception as e:
        return -1, str(e), ''

# Get help text
_, help_out, _ = run_cppcheck(['--help'])

# Extract all options (short and long)
options = []
for line in help_out.split('\n'):
    line = line.strip()
    if line.startswith('-'):
        # Extract options, e.g., -D<ID>, --enable=<severity>, --dump
        # Let's use regex
        matches = re.findall(r'(-[a-zA-Z0-9_]+|--[a-zA-Z0-9_-]+)(?:=([^ ]+)|<([^>]+)>|)', line)
        for m in matches:
            opt = m[0]
            if opt not in options:
                options.append(opt)

print(f"Found {len(options)} options.")

# Probe each option
results = {}
for opt in options:
    res = {}

    # Test alone
    rc, out, err = run_cppcheck([opt])
    res['alone'] = {'rc': rc, 'out': out}

    # Test with empty arg (if it starts with --)
    if opt.startswith('--'):
        rc, out, err = run_cppcheck([f"{opt}="])
        res['empty_eq'] = {'rc': rc, 'out': out}

        rc, out, err = run_cppcheck([f"{opt}=dummy"])
        res['dummy_eq'] = {'rc': rc, 'out': out}
    else:
        # short opt
        rc, out, err = run_cppcheck([opt, ""])
        res['empty_space'] = {'rc': rc, 'out': out}

        rc, out, err = run_cppcheck([opt, "dummy"])
        res['dummy_space'] = {'rc': rc, 'out': out}

    results[opt] = res

with open('db.json', 'w') as f:
    json.dump(results, f, indent=2)

print("Done probing. Results saved to db.json")
EOF
python3 probe.py"}

