import json
import base64
import zlib
import subprocess
import re

def run_cppcheck(args):
    try:
        res = subprocess.run(['./executable'] + args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        return res.returncode, res.stdout.strip()
    except:
        return -1, ''

# Gather data
_, help_out = run_cppcheck(['--help'])
_, version_out = run_cppcheck(['--version'])
_, errorlist_out = run_cppcheck(['--errorlist'])
_, std_cfg_err = run_cppcheck(['dummy_file.c'])

# Compress errorlist
errorlist_zlib = base64.b64encode(zlib.compress(errorlist_out.encode('utf-8'))).decode('ascii')

# Load DB
with open('db.json', 'r') as f:
    db = json.load(f)

# Collect validation rules
rules = {}
for opt, res in db.items():
    rules[opt] = {
        'alone': res['alone']['out'],
    }
    if opt.startswith('--'):
        rules[opt]['empty_eq'] = res.get('empty_eq', {}).get('out', '')
        rules[opt]['dummy_eq'] = res.get('dummy_eq', {}).get('out', '')
    else:
        rules[opt]['empty_space'] = res.get('empty_space', {}).get('out', '')
        rules[opt]['dummy_space'] = res.get('dummy_space', {}).get('out', '')

code = f"""#!/usr/bin/env python3
import sys
import os
import zlib
import base64

help_text = {repr(help_out)}
version_text = {repr(version_out)}
std_cfg_err = {repr(std_cfg_err)}
errorlist_zlib = "{errorlist_zlib}"
rules = {repr(rules)}

def print_err_and_exit(msg):
    print(msg, end='\\n' if msg else '')
    sys.exit(1)

def main():
    args = sys.argv[1:]

    # Pre-pass
    for arg in args:
        if arg in ('-h', '--help'):
            print(help_text)
            sys.exit(0)
        elif arg == '--version':
            print(version_text)
            sys.exit(0)
        elif arg == '--errorlist':
            print(zlib.decompress(base64.b64decode(errorlist_zlib)).decode('utf-8'))
            sys.exit(0)

    files = []
    i = 0
    while i < len(args):
        arg = args[i]

        if arg.startswith('--'):
            if '=' in arg:
                flag, val = arg.split('=', 1)
                if flag not in rules:
                    print_err_and_exit(f'cppcheck: error: unrecognized command line option: "{{arg}}".')
                rule = rules[flag]
                # Validate val
                if val == '':
                    err = rule['empty_eq']
                    if err != "cppcheck: error: no C or C++ source files found.":
                        print_err_and_exit(err)
                else:
                    err = rule['dummy_eq']
                    if err != "cppcheck: error: no C or C++ source files found.":
                        # Some need special checks
                        if flag == '--cppcheck-build-dir':
                            if not os.path.exists(val) or not os.path.isdir(val):
                                print_err_and_exit(f"cppcheck: error: Directory '{{val}}' specified by --cppcheck-build-dir argument has to be existent.")
                        elif flag == '--config-excludes-file':
                            if not os.path.exists(val):
                                print_err_and_exit(f"cppcheck: error: unable to open config excludes file at '{{val}}'")
                        elif flag in ('--suppressions-list', '--file-list', '--exitcode-suppressions'):
                            if not os.path.exists(val):
                                print_err_and_exit(f'cppcheck: error: couldn\\'t open the file: "{{val}}".')
                        elif flag == '--suppress-xml':
                            if not os.path.exists(val):
                                print_err_and_exit(f"cppcheck: error: failed to load suppressions XML '{{val}}' (XML_ERROR_FILE_NOT_FOUND).")
                        elif flag == '--includes-file':
                            if not os.path.exists(val):
                                print_err_and_exit(f"cppcheck: error: unable to open includes file at '{{val}}'")
                        elif flag == '--rule-file':
                            print_err_and_exit("cppcheck: error: Option --rule-file cannot be used as Cppcheck has not been built with rules support.")
                        elif 'unknown' in err or 'not valid' in err or 'empty' in err:
                            # replace dummy with val
                            print_err_and_exit(err.replace('dummy', val))
            else:
                if arg not in rules:
                    print_err_and_exit(f'cppcheck: error: unrecognized command line option: "{{arg}}".')
                rule = rules[arg]
                err = rule['alone']
                if err != "cppcheck: error: no C or C++ source files found.":
                    if err == "cppcheck: Failed to load library configuration file 'std.cfg'. File not found\\nFailed to load std.cfg. Your Cppcheck installation is broken, please re-install. The Cppcheck binary was compiled with FILESDIR set to \\"/usr/local/share/Cppcheck\\" and will therefore search for std.cfg in /usr/local/share/Cppcheck/cfg.":
                        pass # E is special?
                    else:
                        print_err_and_exit(err)

        elif arg.startswith('-') and len(arg) >= 2:
            flag = arg[:2]
            if flag not in rules:
                print_err_and_exit(f'cppcheck: error: unrecognized command line option: "{{flag}}".')
            rule = rules[flag]
            if len(arg) > 2:
                val = arg[2:]
            else:
                if i + 1 < len(args) and not args[i+1].startswith('-'):
                    val = args[i+1]
                    i += 1
                else:
                    err = rule['alone']
                    if err != "cppcheck: error: no C or C++ source files found.":
                        print_err_and_exit(err)
                    val = None

            if val is not None:
                err = rule['dummy_space']
                if err != "cppcheck: error: no C or C++ source files found.":
                    print_err_and_exit(err.replace('dummy', val))
        else:
            files.append(arg)

        i += 1

    if not files:
        print_err_and_exit("cppcheck: error: no C or C++ source files found.")
    else:
        print_err_and_exit(std_cfg_err)

if __name__ == '__main__':
    main()
"""

with open('cppcheck.py', 'w') as f:
    f.write(code)

EOF
