            print_err_str_and_exit("cppcheck: error: Option --rule cannot be used as Cppcheck has not been built with rules support.")
        else:
            print_err_str_and_exit("cppcheck: error: Option --rule-file cannot be used as Cppcheck has not been built with rules support.")
    elif flag in ('--max-configs', '--error-exitcode', '-j', '-l', '--max-ctu-depth'):
        if not is_int(val):
            print_err_str_and_exit(dummy_err.replace('dummy', val))
    elif flag == '--check-level':
        if val not in ('reduced', 'normal', 'exhaustive'):
            print_err_str_and_exit(f"cppcheck: error: unknown '--check-level' value '{val}'.")
    elif flag in ('--enable', '--disable'):
        valid = set(['warning', 'performance', 'portability', 'information', 'style', 'unusedFunction', 'missingInclude', 'all'])
        for v in val.split(','):
            if v not in valid:
                print_err_str_and_exit(f"cppcheck: error: {flag} parameter with the unknown name '{v}'")
    elif flag in ('--language', '-x'):
        if val not in ('c', 'c++'):
            print_err_str_and_exit(f"cppcheck: error: unknown language '{val}' enforced.")
    elif flag == '--output-format':
        if val not in ('text', 'sarif', 'xml', 'xmlv2', 'xmlv3'):
            print_err_str_and_exit(f"cppcheck: error: argument to '--output-format=' must be 'text', 'sarif', 'xml' (deprecated), 'xmlv2' or 'xmlv3'.")
    elif flag == '--platform':
        if val not in ('unix32', 'unix64', 'win32A', 'win32W', 'win64', 'native', 'unspecified'):
            if not os.path.exists(val):
                print_err_str_and_exit(f"cppcheck: error: unrecognized platform: '{val}'.")
    elif flag == '--plist-output':
        if not os.path.isdir(val):
            print_err_str_and_exit(f"cppcheck: error: plist folder does not exist: '{val}'.")
    elif flag == '--report-type':
        valid = set(['normal', 'autosar', 'cert-c-2016', 'cert-cpp-2016', 'misra-c-2012', 'misra-c-2023', 'misra-c-2025', 'misra-cpp-2008', 'misra-cpp-2023'])
        if val not in valid:
            print_err_str_and_exit(f"cppcheck: error: Unknown report type '{val}'")
    elif flag == '--showtime':
        valid = set(['file', 'file-total', 'summary', 'top5_file', 'top5_summary'])
        if val not in valid:
            print_err_str_and_exit(f"cppcheck: error: unrecognized --showtime mode: '{val}'. Supported modes: file, file-total, summary, top5_file, top5_summary.")
    elif flag == '--std':
        valid = set(['c89', 'c99', 'c11', 'c++03', 'c++11', 'c++14', 'c++17', 'c++20'])
        if val not in valid:
            print_err_str_and_exit(f"cppcheck: error: unknown --std value '{val}'")
    else:
        if 'dummy' in dummy_err:
            print_err_str_and_exit(dummy_err.replace('dummy', val))

def main():
    args = sys.argv[1:]

    for arg in args:
        if arg in ('-h', '--help'):
            sys.stdout.buffer.write(HELP_TEXT)
            sys.exit(0)
        elif arg == '--version':
            sys.stdout.buffer.write(VERSION_TEXT)
            sys.exit(0)
        elif arg == '--errorlist':
            sys.stdout.buffer.write(zlib.decompress(base64.b64decode(ERRORLIST_ZLIB)))
            sys.exit(0)

    files = []
    i = 0
    while i < len(args):
        arg = args[i]

        if arg.startswith('--'):
            if '=' in arg:
                flag, val = arg.split('=', 1)
                if flag not in DB:
                    print_err_str_and_exit(f'cppcheck: error: unrecognized command line option: "{arg}".')
                rule = DB[flag]

                if val == '':
                    err = rule.get('empty_eq_out', '')
                    if err and err != NO_FILES_ERR.decode().strip():
                        print_err_str_and_exit(err)
                else:
                    validate_val(flag, val, rule.get('dummy_eq_out', ''))
            else:
                if arg not in DB:
                    print_err_str_and_exit(f'cppcheck: error: unrecognized command line option: "{arg}".')
                rule = DB[arg]
                err = rule['alone_out']
                if err and err != NO_FILES_ERR.decode().strip() and err != STD_CFG_ERR.decode().strip():
                    print_err_str_and_exit(err)
        elif arg.startswith('-') and len(arg) >= 2 and arg != '--':
            flag = arg[:2]
            if flag not in DB:
                print_err_str_and_exit(f'cppcheck: error: unrecognized command line option: "{flag}".')

            rule = DB[flag]
            if len(arg) > 2:
                val = arg[2:]
                validate_val(flag, val, rule.get('dummy_space_out', ''))
            else:
                if i + 1 < len(args) and not args[i+1].startswith('-'):
                    val = args[i+1]
                    i += 1
                    validate_val(flag, val, rule.get('dummy_space_out', ''))
                else:
                    err = rule['alone_out']
                    if err and err != NO_FILES_ERR.decode().strip() and err != STD_CFG_ERR.decode().strip():
                        print_err_str_and_exit(err)
        else:
            if arg != '--':
                files.append(arg)

        i += 1

    if not files:
        print_err_and_exit(NO_FILES_ERR)
    else:
        print_err_and_exit(STD_CFG_ERR)

if __name__ == '__main__':
    main()
